#!/usr/bin/env python3
"""Split the single huge run_trace() generated by Magma into many smaller functions.

- Ciphertext pointers and timers that are used across parts become globals.
- Plaintexts that live inside a single part stay local, so they are freed when that part returns.
- run_trace() in trace_driver.cpp just calls the parts in order.

Usage: split_trace.py <trace.cpp> <output dir> [lines_per_part]
The plaintext files are read from the Files/ directory next to trace.cpp; trace.cpp itself is not modified.
"""
import hashlib
import os
import re
import sys

PARAMS = ("Bootstrapper& bootstrapper, const BootstrappingKey& bk, Encryptor& encryptor, Decryptor& decryptor, "
          "Encryptor& target_encryptor, Decryptor& target_decryptor")
ARGS = "bootstrapper, bk, encryptor, decryptor, target_encryptor, target_decryptor"

RE_CTXT = re.compile(r"^\tCiphertext\* (\w+) = new Ciphertext;$")
RE_PTXT = re.compile(r"^\tPlaintext (\w+);$")
RE_TIME = re.compile(r"^\tauto (\w+) = std::chrono::steady_clock::now\(\);$")
RE_IDENT = re.compile(r"\b[A-Za-z_]\w*\b")
RE_READ = re.compile(r'^\tbootstrapper\.read_plaintext_from_file\((\w+), "(\w+)"\);$')
RE_NTT = re.compile(r"^\tbootstrapper\.transform_to_ntt_inplace\((\w+), (.*)\);$")


def dedup_plaintexts(body, files_dir):
    """Merge plaintexts preloaded in INIT that have identical content and identical NTT transforms.

    INIT loads every plaintext up front and keeps it alive for the whole run, but most of them are
    the same constants (e.g. linear-map diagonals reused by every bootstrapping).
    """
    trace_start = body.index("\t// TRACE")
    reads, ntts = {}, {}
    for l in body[:trace_start]:
        if m := RE_READ.match(l):
            reads[m.group(1)] = m.group(2)
        elif (m := RE_NTT.match(l)) and m.group(1) in reads:
            ntts.setdefault(m.group(1), []).append(m.group(2))

    canonical, rename = {}, {}
    for name, fname in reads.items():
        with open(os.path.join(files_dir, fname), "rb") as f:
            key = (hashlib.md5(f.read()).hexdigest(), tuple(ntts.get(name, [])))
        if key in canonical:
            rename[name] = canonical[key]
        else:
            canonical[key] = name

    out = []
    for i, l in enumerate(body):
        if i < trace_start:
            m = RE_PTXT.match(l) or RE_READ.match(l) or RE_NTT.match(l)
            if m and m.group(1) in rename:
                continue
        if rename and any(n in rename for n in RE_IDENT.findall(l)):
            l = RE_IDENT.sub(lambda m: rename.get(m.group(0), m.group(0)), l)
        out.append(l)
    return out, len(reads), len(canonical)


def main():
    trace_file, out_dir = sys.argv[1], sys.argv[2]
    per_part = int(sys.argv[3]) if len(sys.argv) > 3 else 4000
    os.makedirs(out_dir, exist_ok=True)

    with open(trace_file) as f:
        lines = f.read().split("\n")
    start = next(i for i, l in enumerate(lines) if l.startswith("{")) + 1
    end = max(i for i, l in enumerate(lines) if l.startswith("}"))
    body = [l for l in lines[start:end] if l.strip()]
    files_dir = os.path.join(os.path.dirname(os.path.abspath(trace_file)), "Files")
    body, nb_ptxt, nb_unique = dedup_plaintexts(body, files_dir)

    parts = [body[i:i + per_part] for i in range(0, len(body), per_part)]

    # Declarations
    ctxts, timers, ptxt_part = set(), set(), {}
    for p, part in enumerate(parts):
        for l in part:
            if m := RE_CTXT.match(l):
                ctxts.add(m.group(1))
            elif m := RE_TIME.match(l):
                timers.add(m.group(1))
            elif m := RE_PTXT.match(l):
                ptxt_part[m.group(1)] = p

    # Plaintexts used outside their declaring part must become globals
    tracked = ctxts | timers | set(ptxt_part)
    used = []
    for p, part in enumerate(parts):
        names = set()
        for l in part:
            names.update(n for n in RE_IDENT.findall(l) if n in tracked)
        used.append(names)
    global_ptxts = {n for p, names in enumerate(used) for n in names if n in ptxt_part and ptxt_part[n] != p}

    # Global definitions
    with open(os.path.join(out_dir, "trace_globals.cpp"), "w") as f:
        f.write('#include "trace.h"\n\n')
        for n in sorted(ctxts):
            f.write(f"Ciphertext* {n} = nullptr;\n")
        for n in sorted(timers):
            f.write(f"std::chrono::steady_clock::time_point {n};\n")
        # Plaintext objects need SEAL's memory pool, which does not exist yet during static initialization,
        # so shared plaintexts are heap-allocated in INIT and accessed through a macro
        for n in sorted(global_ptxts):
            f.write(f"Plaintext* {n}__p = nullptr;\n")

    # Parts
    for p, part in enumerate(parts):
        with open(os.path.join(out_dir, f"trace_part{p:04d}.cpp"), "w") as f:
            f.write('#include "trace.h"\n\n')
            for n in sorted(used[p]):
                if n in ctxts:
                    f.write(f"extern Ciphertext* {n};\n")
                elif n in timers:
                    f.write(f"extern std::chrono::steady_clock::time_point {n};\n")
                elif n in global_ptxts:
                    f.write(f"extern Plaintext* {n}__p;\n#define {n} (*{n}__p)\n")
            f.write(f"\nvoid run_trace_part{p:04d}({PARAMS})\n{{\n")
            for l in part:
                if m := RE_CTXT.match(l):
                    l = f"\t{m.group(1)} = new Ciphertext;"
                elif m := RE_TIME.match(l):
                    l = f"\t{m.group(1)} = std::chrono::steady_clock::now();"
                elif (m := RE_PTXT.match(l)) and m.group(1) in global_ptxts:
                    l = f"\t{m.group(1)}__p = new Plaintext;"
                f.write(l + "\n")
            f.write("}\n")

    # Driver
    with open(os.path.join(out_dir, "trace_driver.cpp"), "w") as f:
        f.write('#include "trace.h"\n\n')
        for p in range(len(parts)):
            f.write(f"void run_trace_part{p:04d}({PARAMS});\n")
        f.write(f"\nvoid run_trace({PARAMS})\n{{\n")
        for p in range(len(parts)):
            f.write(f"\trun_trace_part{p:04d}({ARGS});\n")
        f.write("}\n")

    print(f"merged plaintexts: {nb_ptxt} -> {nb_unique}")
    print(f"split {len(body)} lines into {len(parts)} parts "
          f"({len(ctxts)} ciphertexts, {len(global_ptxts)}/{len(ptxt_part)} plaintexts global)")


if __name__ == "__main__":
    main()
